import zeros = require( '@stdlib/ndarray/zeros' );
import add4 = require( '@stdlib/number/float64/base/add4' );
import quaternary = require( './index' );


// TESTS //

// The function returns `undefined`...
{
	const x = zeros( [ 2, 2 ] );
	const y = zeros( [ 2, 2 ] );
	const z = zeros( [ 2, 2 ] );
	const w = zeros( [ 2, 2 ] );
	const u = zeros( [ 2, 2 ] );
	const arrays = [ x, y, z, w, u ];

	quaternary( arrays, add4 ); // $ExpectType void
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object containing ndarray-like objects...
{
	quaternary( 5, add4 ); // $ExpectError
	quaternary( true, add4 ); // $ExpectError
	quaternary( false, add4 ); // $ExpectError
	quaternary( null, add4 ); // $ExpectError
	quaternary( undefined, add4 ); // $ExpectError
	quaternary( {}, add4 ); // $ExpectError
	quaternary( [ 1 ], add4 ); // $ExpectError
	quaternary( ( x: number ): number => x, add4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a quaternary function...
{
	const x = zeros( [ 2, 2 ] );
	const y = zeros( [ 2, 2 ] );
	const z = zeros( [ 2, 2 ] );
	const w = zeros( [ 2, 2 ] );
	const u = zeros( [ 2, 2 ] );
	const arrays = [ x, y, z, w, u ];

	quaternary( arrays, '10' ); // $ExpectError
	quaternary( arrays, 5 ); // $ExpectError
	quaternary( arrays, true ); // $ExpectError
	quaternary( arrays, false ); // $ExpectError
	quaternary( arrays, null ); // $ExpectError
	quaternary( arrays, undefined ); // $ExpectError
	quaternary( arrays, [] ); // $ExpectError
	quaternary( arrays, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ] );
	const y = zeros( [ 2, 2 ] );
	const z = zeros( [ 2, 2 ] );
	const w = zeros( [ 2, 2 ] );
	const u = zeros( [ 2, 2 ] );
	const arrays = [ x, y, z, w, u ];

	quaternary(); // $ExpectError
	quaternary( arrays ); // $ExpectError
	quaternary( arrays, add4, 10 ); // $ExpectError
}
